UPDATE world.playerchoice_response SET `Description`='Убийцы Королей – кинжалы Гароны, которыми она убивала неугодных Гул\'дану. Они отравляют жертву ядом, не оставляющим следов, поэтому когда Убийцы Королей решают чью-то судьбу, это невозможно доказать.\n\nДушевные муки вынудили Гарону спрятать кинжалы, но позже она вернулась за ними, чтобы одолеть опасных служителей Легиона.\n\nМы должны ее найти.' WHERE ChoiceId=262 AND ResponseId=568;
