UPDATE world.playerchoice_response SET `Description`='Жуткий адмирал Элиза – гроза Южных морей. Ее проклятые клинки нагоняют ужас на многих.\n\nМы узнали, что ее корабль бросил якорь у берегов Азсуны на Расколотых островах. Если поспешить, то можно заполучить ее клинки.' WHERE ChoiceId=262 AND ResponseId=569;
