UPDATE world.playerchoice_response SET `Description`='Акаари Кровавая Тьма – непревзойденная эредарская убийца, предмет особой гордости Легиона. Ее кинжалы способны искажать пространство, скрывая своего владельца в тени.\n\nУ нас есть данные разведки, указывающие, где она находится в настоящее время. Пора нанести удар.' WHERE ChoiceId=262 AND ResponseId=570;
